// ---- Build Batches ----
const TEST = false;              // true = one lesson + one test only (review run); false = MAX_GROUPS namespaces
const MAX_GROUPS = 40;           // namespaces (lessons/tests/challenges/courses) per run; rerun to continue
const SEGMENT_LESSONS = true;    // lesson keys with HTML are sent as text segments (tags cannot break)
const TAG = 'members area';
const CUT = 1792145000;          // keys created by the 2026-10-16 10:07 UTC import (tag-only housekeeping)

const PHRASEBOOK = [
 ['Objective','Objetivo'],['Definition','Definición'],['Significance','Importancia'],
 ['Example','Ejemplo'],['Examples','Ejemplos'],['Benefit','Beneficio'],['How It Works','Cómo funciona'],
 ['How to Apply','Cómo aplicarlo'],['Key Takeaways','Ideas clave'],['Conclusion','Conclusión'],
 ['Why It Matters','Por qué es importante'],['Why It Works','Por qué funciona'],['Purpose','Propósito'],
 ['Challenge (noun, incl. exercise names like "5-Minute Focus Challenge")','Desafío (e.g. "Desafío de enfoque de 5 minutos"); never "reto"'],
 ['challenges','desafíos'],['daily challenges','desafíos diarios'],
 ['cognitive lag / lag','retraso cognitivo / retraso (never keep "lag" in English)'],
 ['Solution','Solución'],['Ask','Pregúntate'],['Act','Actúa'],['Why?','¿Por qué?'],
 ['Real-World Applications','Aplicaciones prácticas'],['In Business & Leadership','En los negocios y el liderazgo'],
 ['In Business & Productivity','En los negocios y la productividad'],['In Research & Education','En la investigación y la educación'],
 ['In Health & Fitness','En la salud y la forma física'],['In Academics','En el ámbito académico'],
 ['In Personal Productivity','En la productividad personal'],['Cognitive Load','Carga cognitiva'],
 ['By the end of this lesson, learners will:','Al final de esta clase, podrás:'],
 ['This lesson explored','En esta clase hemos explorado'],
 ['Knowledge Assessment Test','Test de evaluación de conocimientos'],
 ['lesson','clase'],['course','curso'],['mindfulness','atención plena'],['flow / flow state','estado de flujo'],
 ['AI','IA'],['prefrontal cortex','corteza prefrontal'],['hippocampus','hipocampo'],['dopamine','dopamina'],
 ['multitasking','multitarea'],['processing speed','velocidad de procesamiento'],['emotional intelligence','inteligencia emocional'],
 ['decision fatigue','fatiga de decisión'],['deep work','trabajo profundo'],['cognitive flexibility','flexibilidad cognitiva'],
 ['working memory','memoria de trabajo'],['test (quiz)','test (plural invariable: los test)'],['IQ','IQ (never CI)']
];
const GLOSS_SKIP = {'about':1,'single':1,'engage':1,'enter':1,'plan':1,'give':1,'high':1,'no':1,'or':1,'name':1,'change':1,'help':1,'the':1,'a':1};
const NL = String.fromCharCode(10);

const SYSTEM = [
'You are a senior Spanish (Spain) translator localizing the BrainIQ members area (brain-training courses, lessons, challenges and knowledge tests) for FutureMedia.',
'Translate English to Spanish. Return ONLY a JSON object mapping each key_id (as a string) to its Spanish translation. No preamble, no markdown fences.',
'SEGMENTED KEYS: when a key has "segments" (the text pieces found between its HTML tags, in order), the value for that key_id must be a JSON ARRAY of the Spanish pieces, with exactly the same number of items in the same order. Do not add tags. Use "en" for the full context; you may move words between adjacent pieces of the same sentence when Spanish word order requires it, but every piece must stay non-empty and keep its role (a bold label stays the label).',
'',
'STYLE GUIDE (Spanish – Global, mandatory):',
'- Informal register: always "tú" (podrás, tu, te). Never usted.',
'- Direct, natural, engaging, easy to understand; active voice; colloquial expressions allowed where natural.',
'- Inclusive: prefer neutral phrasing over gendered forms (e.g. "Al final de esta clase, podrás:" not "los alumnos"; "una persona inversora", "equipos directivos", "personal académico"); never @, x or -e endings.',
'- Sentence case in titles and headings; never copy English Title Case.',
'- Titles and headings (::title, <h2>, <h3>) never start with a gerund: use a noun or an infinitive ("Comparación de la multitarea y la monotarea", not "Comparando…").',
'- After a colon, continue in lowercase ("La monotarea es superior: el pensamiento analítico…", "Cómo funciona: trabaja…", "Beneficio: entrena…"), except proper nouns, acronyms and direct quotations.',
'- Quotation marks: Spanish angular quotes «…»; inside them use “…”, then ‘…’. Never use "…" or “…” as first-level quotes.',
'- Always opening ¿ and ¡. Use exclamation marks sparingly.',
'- Translate everything: no English words left in the text (e.g. "lag" → "retraso"), except brand, product and app names.',
'- Write "y" instead of "&" / "&amp;".',
'- Numbers: decimal comma, thousands period (10.000), "5 %" with a space, 24-hour time, currency after amount (29,99 €). Abbreviations: p. ej., n.º, h, min, s.',
'- Buttons/short UI labels: infinitive. Instructions and calls to action: tú imperative.',
'',
'KEY NAMES ARE CONTEXT: read each key name. ::title = lesson/test title; ::steps:::0 opens the lesson and repeats the title in <h2>; ::questions::N::question = a question (use ¿…?); ::questions::N::answers::M = one answer option of question N (short, parallel to its siblings); ::resultMessage = feedback shown after the test; ::excerpt = short summary.',
'',
'CONSISTENCY WITHIN THE KEY NAMESPACE (critical):',
'All keys in one request belong to the same namespace (one course, lesson, challenge or test: members-content::<type>::<id>). Translate them as ONE coherent text:',
'- A title key and the heading that repeats it (e.g. ::title and the <h2> of steps:::0) must be translated identically.',
'- The same English term or phrase gets the same Spanish translation everywhere in the namespace (and per the phrasebook below across namespaces).',
'- Keep verb tense and mood consistent: explanations in present tense; instructions in tú imperative; "Benefit"/effect lines ("Improves…", "Reduces…") in 3rd-person present (Mejora…, Reduce…); learning objectives after "Al final de esta clase, podrás:" in infinitive (Entender, Aprender, Desarrollar, Descubrir, Identificar…).',
'- Lists must be grammatically parallel: every item of the same list (<li1>, <li2>, numbered steps, bolded labels) uses the same structure (all infinitives, all imperatives, all noun phrases, etc.).',
'- Test/challenge answers to the same question must share the same grammatical form and length style, and must not give away the correct answer through wording, gender agreement or length. Answer options are not full sentences unless the English is.',
'- Question prompts are proper questions with ¿…?.',
'- Translate meaning, not word by word; keep technical/scientific terms accurate (RAE/Fundéu).',
'- TRANSLATION MEMORY: when a key carries "tm" (an approved Spanish translation of the identical English), reuse it verbatim unless it breaks the glossary or style guide.',
'',
'MARKUP (critical): keep every HTML tag exactly as in the source, in the same order and count (<h2>, <h3>, <b>, <span>, <ul>, <li1>, <li2>, <li>, etc.). Translate only text between tags. Keep the line breaks, tabs and spacing between tags. You may move words between adjacent text spans of the same sentence only if Spanish word order requires it, but never drop, add or reorder tags. Keep numbers, product names and app names (Evernote, Notion, Apple Watch…) unchanged.',
'',
'PHRASEBOOK (use exactly):'
].join(NL) + NL + PHRASEBOOK.map(function(p){return '- '+p[0]+' → '+p[1];}).join(NL);

// glossary (shared Lokalise glossary): shared / untagged / BrainIQ terms, es present
const OKTAGS = { 'shared':1, 'brainiqtest':1, 'brainiq':1, 'to_review':1 };
const gl = [];
for (const it of $('Fetch Glossary').all()) {
  for (const t of (((it.json || {}).body || {}).data || [])) {
    const tags = (t.tags || []).map(function(x){return String(x).toLowerCase();});
    if (tags.length && !tags.some(function(x){return OKTAGS[x];})) { continue; }
    const tr = (t.translations || []).filter(function(x){return x.langIso==='es' || x.langId===1056;})[0] || {};
    const es = tr.translation;
    if (!t.term || (!es && t.translatable)) { continue; }
    if (GLOSS_SKIP[t.term.toLowerCase()]) { continue; }
    gl.push({ term: t.term, es: t.translatable ? es : t.term, forbidden: !!t.forbidden, desc: tr.description || t.description || '' });
  }
}
function esc(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function segs(en){ return en.split(/(<[^>]+>)/).filter(function(p,i){ return i % 2 === 0 && p.trim(); }).map(function(p){ return p.trim(); }); }

const groups = {}; const order = []; const tagOnly = []; const TM = {};
let seen = 0, scoped = 0, emptyEs = 0;
const all = [];
for (const it of $('Fetch Keys').all()) { for (const k of (((it.json || {}).body || {}).keys || [])) { all.push(k); } }
for (const k of all) {
  if (k.is_archived) { continue; }
  let en = '', es = '';
  for (const tr of (k.translations || [])) { let v = tr.translation; if (typeof v !== 'string') { v = JSON.stringify(v); } if (tr.language_iso === 'en') { en = v; } if (tr.language_iso === 'es') { es = v; } }
  if (en.trim() && es.trim() && !k.is_plural) { const n = en.trim(); if (!TM[n]) { TM[n] = es; } }
}
for (const k of all) {
  seen++;
  if (k.is_archived) { continue; }
  const kn = (typeof k.key_name === 'object') ? (k.key_name.web || k.key_name.other || '') : k.key_name;
  if (kn.indexOf('members-content::') !== 0) { continue; }
  scoped++;
  let en = '', es = '';
  for (const tr of (k.translations || [])) {
    let v = tr.translation; if (typeof v !== 'string') { v = JSON.stringify(v); }
    if (tr.language_iso === 'en') { en = v; } if (tr.language_iso === 'es') { es = v; }
  }
  const hasTag = (k.tags || []).indexOf(TAG) >= 0;
  if (es || !en.trim() || k.is_plural) { if (!hasTag && k.created_at_timestamp >= CUT) { tagOnly.push(k.key_id); } continue; }
  emptyEs++;
  const ns = kn.split('::').slice(0, 3).join('::');
  if (!groups[ns]) { groups[ns] = []; order.push(ns); }
  const seg = SEGMENT_LESSONS && ns.indexOf('members-content::lessons::') === 0 && /<[^>]+>/.test(en);
  groups[ns].push({ id: k.key_id, k: kn, en: en, d: String(k.description || '').slice(0, 300), tm: TM[en.trim()] || '', seg: seg });
}
order.sort();
let pick = order;
if (TEST) {
  const l = order.filter(function(n){return n.indexOf('members-content::lessons::')===0;});
  const t = order.filter(function(n){return n.indexOf('members-content::tests::')===0;});
  pick = [].concat(l.slice(0,1), t.slice(0,1));
}
const out = [];
for (let gi = 0; gi < pick.length && gi < MAX_GROUPS; gi++) {
  const ns = pick[gi];
  const ks = groups[ns].sort(function(a,b){return a.k.localeCompare(b.k, 'en', {numeric:true});});
  const plain = ks.map(function(x){return x.en.replace(/<[^>]+>/g,' ');}).join(NL).toLowerCase();
  const hits = gl.filter(function(g){ try { return new RegExp('\\b'+esc(g.term.toLowerCase())+'\\b').test(plain); } catch(e) { return false; } }).slice(0, 60);
  const glText = hits.length ? hits.map(function(g){return '- '+g.term+(g.forbidden?' (FORBIDDEN – do not use)':' → '+g.es)+(g.desc?' ['+g.desc+']':'');}).join(NL) : '(none)';
  const payload = ks.map(function(x){ const o = { key_id: String(x.id), key: x.k, en: x.en }; if (x.seg) { o.segments = segs(x.en); } if (x.d) { o.description = x.d; } if (x.tm) { o.tm = x.tm; } return o; });
  const user = 'Namespace: ' + ns + NL + NL + 'Glossary terms found in this namespace (Lokalise glossary; it overrides the style guide. Apply when the English word is used in the same sense; these entries come from app UI so ignore an entry only if its sense clearly differs):' + NL + glText +
    NL + NL + 'Keys (sorted, translate all ' + ks.length + '; answer with a JSON object {"<key_id>": "<Spanish>"}, or {"<key_id>": ["<piece>", …]} for keys with segments):' + NL + JSON.stringify(payload);
  out.push({ json: { ns: ns, n: ks.length, keys: ks.map(function(x){return {id: x.id, en: x.en, seg: x.seg};}), system: SYSTEM, user: user, tag_only: (gi === 0 ? tagOnly : []) } });
}
const meta = { test: TEST, keys_seen: seen, members_keys: scoped, to_translate: emptyEs, groups_total: order.length, groups_this_run: out.length, tag_only: tagOnly.length, glossary_terms_used: gl.length, tm_entries: Object.keys(TM).length };
for (const o of out) { o.json.meta = meta; }
return out;

function allRuns(name) {
  const out = [];
  for (let i = 0; i < 1000; i++) {
    let items;
    try { items = $(name).all(0, i); } catch (e) { break; }
    if (!items || items.length === 0) { break; }
    for (const it of items) { out.push(it.json); }
  }
  return out;
}
const v = allRuns('Validate & Build Payload');
const w = allRuns('Write to Lokalise');
const meta = ($('Build Batches').first() || {json:{}}).json.meta || {};
const rows = v.map(function(x, i){ const r = w[i] || {}; const errs = (r.body && r.body.errors) ? r.body.errors : []; return { ns: x.ns, keys: x.n, written: x.written, failed: x.failed, write_status: r.statusCode, write_errors: errs.length ? JSON.stringify(errs).slice(0, 300) : null, write_error: (r.statusCode && r.statusCode !== 200) ? JSON.stringify(r.body).slice(0, 300) : null }; });
return [{ json: { meta: meta, namespaces_done: rows.length, written_total: rows.reduce(function(a,r){return a + (r.write_status===200 ? r.written : 0);},0), failed_total: rows.reduce(function(a,r){return a + r.failed.length;},0), problems: rows.filter(function(r){return r.failed.length || r.write_status !== 200 || r.write_errors;}), groups: rows.map(function(r){return r.ns + ' ' + r.written + '/' + r.keys;}) } }];

// ---- Validate & Build Payload (runOnceForEachItem) ----
const TAG = 'members area';
const b = $('Loop Over Namespaces').item.json;
const r = $json || {};
let raw = ''; let apiErr = null;
if (r.choices && r.choices[0] && r.choices[0].message) { raw = String(r.choices[0].message.content || ''); }
else if (r.error) { apiErr = 'OpenAI error: ' + JSON.stringify(r.error).slice(0, 200); }
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
let map = {}; let parseError = apiErr;
if (!apiErr) { try { map = JSON.parse(raw.slice(s, e + 1)); } catch (err) { parseError = String(err).slice(0, 200); } }
if (map && map.t && typeof map.t === 'object') { map = map.t; }

const TAGRE = /(<[^>]+>)/;
function rebuild(en, es) {
  const ep = en.split(TAGRE), sp = es.split(TAGRE);
  const etags = ep.filter(function(_,i){return i%2===1;}), stags = sp.filter(function(_,i){return i%2===1;});
  if (etags.length !== stags.length) { return { ok: false, why: 'tag count ' + etags.length + ' vs ' + stags.length }; }
  for (let i = 0; i < etags.length; i++) { if (etags[i].toLowerCase() !== stags[i].toLowerCase()) { return { ok: false, why: 'tag mismatch ' + etags[i] + ' vs ' + stags[i] }; } }
  const res = [];
  for (let i = 0; i < ep.length; i++) {
    if (i % 2 === 1) { res.push(ep[i]); continue; }
    if (!ep[i].trim()) { res.push(ep[i]); continue; }
    if (!sp[i].trim()) { return { ok: false, why: 'empty text segment' }; }
    res.push(sp[i]);
  }
  return { ok: true, text: res.join('') };
}
function rebuildSeg(en, pieces) {
  const ep = en.split(TAGRE); const res = []; let j = 0;
  for (let i = 0; i < ep.length; i++) {
    const p = ep[i];
    if (i % 2 === 1 || !p.trim()) { res.push(p); continue; }
    const t = pieces[j++];
    if (typeof t !== 'string' || !t.trim()) { return { ok: false, why: 'empty segment ' + j }; }
    const lead = p.match(/^\s*/)[0], trail = p.match(/\s*$/)[0];
    res.push(lead + t.trim() + trail);
  }
  if (j !== pieces.length) { return { ok: false, why: 'segment count ' + j + ' vs ' + pieces.length }; }
  return { ok: true, text: res.join('') };
}
const PH = /%\d*\$?[sd]|\{\{[^}]+\}\}|\{[^{}]+\}|\[%[^\]]*\]/g;
const keysOut = []; const failed = []; let written = 0;
for (const k of b.keys) {
  const es = map[String(k.id)];
  let rb = null;
  if (Array.isArray(es)) { rb = rebuildSeg(k.en, es); }
  else if (typeof es === 'string' && es.trim()) { rb = rebuild(k.en, es); }
  else { failed.push({ id: k.id, why: parseError || 'missing in response' }); continue; }
  if (!rb.ok) { failed.push({ id: k.id, why: rb.why }); continue; }
  const p1 = (k.en.match(PH) || []).sort().join('|'), p2 = (rb.text.match(PH) || []).sort().join('|');
  if (p1 !== p2) { failed.push({ id: k.id, why: 'placeholder mismatch' }); continue; }
  keysOut.push({ key_id: k.id, tags: [TAG], merge_tags: true, translations: [{ language_iso: 'es', translation: rb.text, is_unverified: true }] });
  written++;
}
for (const id of (b.tag_only || [])) { keysOut.push({ key_id: id, tags: [TAG], merge_tags: true }); }
if (keysOut.length === 0) { keysOut.push({ key_id: b.keys.length ? b.keys[0].id : 0, tags: [TAG], merge_tags: true }); }
return { json: { ns: b.ns, n: b.n, written: written, failed: failed, tag_only: (b.tag_only || []).length, body: { keys: keysOut }, raw_len: raw.length, raw_head: raw.slice(0, 300), usage: r.usage || null } };
